# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TEKNOLOJİ BAĞLAMINDA ONTOLOJİK PROBLEMLER</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Ontolojik Anlam Kaybı (Heidegger)</text>\n  <text x="50" y="103" font-size="11" fill="#334155">• Çerçeveleme (Ge-stell): Modern teknoloji</text>\n  <text x="60" y="120" font-size="10.5" fill="#475569">doğayı kendi başına değerli bir varlık</text>\n  <text x="60" y="137" font-size="10.5" fill="#475569">olarak değil, tüketilecek \'rezerv/stok\'</text>\n  <text x="60" y="154" font-size="10.5" fill="#475569">(Bestand) olarak görür.</text>\n  <text x="50" y="178" font-size="11" fill="#334155">• Varlığın araçsallaştırılması sonucu</text>\n  <text x="60" y="195" font-size="10.5" fill="#475569">doğa ve insan ontolojik anlamını yitirir.</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Teknolojik Yabancılaşma</text>\n  <text x="380" y="103" font-size="11" fill="#334155">• İnsanın kendi ürettiği teknik araçların</text>\n  <text x="390" y="120" font-size="10.5" fill="#475569">ve algoritmaların denetimine girmesi.</text>\n  <text x="380" y="143" font-size="11" fill="#334155">• Yabancılaşmanın Dört Boyutu:</text>\n  <text x="390" y="160" font-size="10.5" fill="#475569">1. Emeğine ve ürettiği ürüne yabancılaşma</text>\n  <text x="390" y="177" font-size="10.5" fill="#475569">2. Doğaya ve fiziksel çevreye yabancılaşma</text>\n  <text x="390" y="194" font-size="10.5" fill="#475569">3. Kendine ve insani özüne yabancılaşma</text>\n  <text x="390" y="211" font-size="10.5" fill="#475569">4. Topluma ve yüz yüze iletişime yabancılaşma</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SANAL GERÇEKLİK, SİMÜLASYON VE YAPAY ZEKÂ ONTOLOJİSİ</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sanal Gerçeklik ve Hipergerçeklik</text>\n  <text x="50" y="103" font-size="11" fill="#334155">• Jean Baudrillard: Simülasyon Kuramı</text>\n  <text x="50" y="123" font-size="10.5" fill="#475569">- Simülakr: Gerçek bir kökeni olmayan,</text>\n  <text x="60" y="140" font-size="10.5" fill="#475569">gerçeğin yerini alan kopya/görüntü.</text>\n  <text x="50" y="162" font-size="10.5" fill="#475569">- Hipergerçeklik: Sanal ortamın gerçek</text>\n  <text x="60" y="179" font-size="10.5" fill="#475569">dünyadan daha gerçek algılanması.</text>\n  <text x="185" y="212" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">&quot;Gerçek nedir?&quot; sorusu yeniden tanımlanır</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Yapay Zekâ ve Zihin Felsefesi</text>\n  <text x="380" y="103" font-size="11" fill="#334155">• Alan Turing (Turing Testi): Makineler</text>\n  <text x="390" y="120" font-size="10.5" fill="#475569">insan gibi düşünebilir mi?</text>\n  <text x="380" y="143" font-size="11" fill="#334155">• John Searle (Çince Odası Deneyi):</text>\n  <text x="390" y="160" font-size="10.5" fill="#475569">Sembol işlemek (sentaks), anlamak ve</text>\n  <text x="390" y="177" font-size="10.5" fill="#475569">bilinç sahibi olmak (semantik) değildir.</text>\n  <text x="515" y="212" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#854d0e">Zayıf YZ (Araç) vs. Güçlü YZ (Bilinç İddiası)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TRANSHÜMANİZM VE POSTHÜMANİZM TARTIŞMALARI</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Transhümanizm İddiası</text>\n  <text x="40" y="105" font-size="10.5" fill="#334155">• Biyoteknoloji, genetik</text>\n  <text x="48" y="122" font-size="10.5" fill="#475569">mühendisliği ve nöroteknoloji</text>\n  <text x="48" y="139" font-size="10.5" fill="#475569">ile insanın biyolojik ve</text>\n  <text x="48" y="156" font-size="10.5" fill="#475569">bilişsel sınırlarını aşma,</text>\n  <text x="48" y="173" font-size="10.5" fill="#475569">yaşlanmayı durdurma hedefi.</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Felsefi ve Etik Eleştiriler</text>\n  <text x="262" y="105" font-size="10.5" fill="#334155">• Francis Fukuyama &amp; Habermas:</text>\n  <text x="262" y="125" font-size="10.5" fill="#475569">- İnsan doğasının (özünün)</text>\n  <text x="270" y="142" font-size="10.5" fill="#475569">ve onurunun zedelenmesi.</text>\n  <text x="262" y="162" font-size="10.5" fill="#475569">- Biyolojik eşitsizlik ve yeni</text>\n  <text x="270" y="179" font-size="10.5" fill="#475569">sınıfsal uçurumlar riski.</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İnsan Merkezli Denge</text>\n  <text x="485" y="105" font-size="10.5" fill="#334155">• Teknoloji insanı nesneleştiren</text>\n  <text x="493" y="122" font-size="10.5" fill="#475569">bir amaç değil, insan onuruna</text>\n  <text x="493" y="139" font-size="10.5" fill="#475569">hizmet eden bir araç olmalıdır.</text>\n  <text x="485" y="162" font-size="10.5" fill="#334155">• Ahlaki öznellik ve irade</text>\n  <text x="493" y="179" font-size="10.5" fill="#475569">korunmalıdır (FEL.11.2.2).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
